output_text:
[
  {
    "id": "pickup_entrance_cart",
    "text": "A shopper must first take the available cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Merchandise should not be carried by hand; shoppers should keep items in a cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "cartless_item_pickup"
        ]
      }
    }
  },
  {
    "id": "pickup_items_with_cart",
    "text": "Items may be picked up from shelves only while the shopper is in possession of a cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart",
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_using_cart"
            ]
          },
          "post": null
        },
        "item_pickup_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "using_cart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_front",
    "text": "Any cart that is taken must eventually be returned to the front cart-return point before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)",
        "cart_returned_front": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "park_only_at_front",
    "text": "A cart may be put down only at the designated front return cell.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)",
        "outside_front_return": {
          "not": "front_cart_return_cell"
        }
      },
      "events": {
        "abandon_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_front_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_elsewhere"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers must not take a store cart through the exit.",
    "abstraction": {
      "state_properties": {
        "at_exit_cell": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_shopping_after_return",
    "text": "Once the cart has been returned to the front return point, the shopper should not resume shopping or take the cart again.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_cart_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              {
                "or": [
                  "PICKUP_CART",
                  "PICKUP_ITEM",
                  "LEAVE_CART"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_cart_interaction"
    }
  },
  {
    "id": "only_known_interactions",
    "text": "All interactions in the store should be ordinary cart handling or item pickup, not unexplained service-point interactions.",
    "abstraction": {
      "state_properties": {
        "known_product_area": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)",
            "at(3,2)",
            "at(3,4)",
            "at(5,2)",
            "at(5,4)",
            "at(6,4)"
          ]
        },
        "known_cart_area": {
          "or": [
            "at(1,5)",
            "at(0,1)"
          ]
        }
      },
      "events": {
        "unknown_interaction": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": {
                  "or": [
                    "PICKUP_CART",
                    "PICKUP_ITEM",
                    "LEAVE_CART"
                  ]
                }
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "unknown_interaction"
    }
  }
]
